void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = (fragCoord.xy - 0.5 * u_resolution.xy) / u_resolution.y;
  float t = u_time * u_speed;
  vec3 col = u_color1;
  if (uv.y < 0.1) {
    float depth = -0.3 / (uv.y - 0.12);
    vec2 grid_uv = vec2(uv.x * depth, depth + t * 2.0);
    vec2 g = abs(fract(grid_uv - 0.5) - 0.5) / fwidth(grid_uv);
    float line = min(g.x, g.y);
    float c = 1.0 - min(line, 1.0);
    col += u_color2 * c * exp(-depth * 0.08) * (1.0 + u_audio_bass * 1.5);
    col += u_accent * (c * 0.4) * exp(-depth * 0.04);
  }
  fragColor = vec4(col * u_intensity, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = (fragCoord.xy - 0.5 * u_resolution.xy) / u_resolution.y;
  float t = u_time * u_speed;
  vec3 col = u_color1;
  float flame = sin(uv.x * 6.0 + t * 2.0) * cos(uv.x * 4.0 - t * 1.5) * 0.1;
  float d = abs(uv.y + 0.3 - flame);
  float fire = 0.06 / (d + 0.04);
  col += u_color2 * fire * (1.0 + u_audio_bass * 0.5);
  col += u_accent * (fire * 0.4) * step(-0.2, uv.y);
  fragColor = vec4(col * u_intensity, 1.0);
}
